export function NavIcon({
  filled = false,
  name,
}: {
  filled?: boolean;
  name: NavigationItemKey;
}) {
  if (name === "forum") {
    return <HomeIcon filled={filled} />;
  }

  if (name === "psychologists") {
    return <SpecialistsIcon filled={filled} />;
  }

  if (name === "profile") {
    return <ProfileIcon />;
  }

  if (name === "bookmarks") {
    return <BookmarkIcon filled={filled} />;
  }

  if (name === "drafts") {
    return <DraftIcon />;
  }

  return <SettingsIcon filled={filled} />;
}

